def rec(n):
    if n == 0: return 0
    return n ____ rec(n - 1)

def fib(n):
    if n ____ 2:
        return n
    return fib(n-1) + fib(n-2)

def fact(n):
    if n == 0:
        return 1
    return n ____ fact(n - 1)

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) ____ fib(n - 2)
